    usage();
}

# Extract the number of whole seconds from the input argument
my $whole_seconds = int($seconds);

# Extract the fraction of a second, if any, from the input argument
my $fraction = $seconds - $whole_seconds;

# Sleep for the whole number of seconds using the built-in sleep function
sleep $whole_seconds;

# If there is a fraction of a second, use Time::HiRes::tv_interval to sleep
# for the remaining time with sub-second precision
if ($fraction) {
