```cpp
function computeImpliedVolatility(
  underlyingPrice: number, // S
  strikePrice: number, // K
  riskFreeRate: number, // r
  optionPrice: number, // C
  timeToExpiration: number, // T
  optionType: 'call' | 'put', // either a call or a put option
): number {
  const tolerance = 0.00001; // set the tolerance level for convergence
  const maxIterations = 100; // set the maximum number of iterations to prevent infinite loops
  let sigma = 0.5; // set an initial value for sigma, the implied volatility

  for (let i = 0; i < maxIterations; i++) {
    const d1 =
      (Math.log(underlyingPrice / strikePrice) + (riskFreeRate + (sigma * sigma) / 2) * timeToExpiration) /
      (sigma * Math.sqrt(timeToExpiration));
    const d2 = d1 - sigma * Math.sqrt(timeToExpiration);
    const optionPriceCalculated =
      optionType === 'call'
        ? underlyingPrice * normCDF(d1) - strikePrice * Math.exp(-riskFreeRate * timeToExpiration) * normCDF(d2)
        : strikePrice * Math.exp(-riskFreeRate * timeToExpiration) * normCDF(-d2) - underlyingPrice * normCDF(-d1);
    const vega =
      underlyingPrice * Math.sqrt(timeToExpiration) * normPDF(d1) * Math.exp(-d1 * d1 / 2) / Math.sqrt(2 * Math.PI);

    if (Math.abs(optionPriceCalculated - optionPrice) < tolerance) {
      // if the calculated option price is close enough to the actual option price, return the implied volatility
      return sigma;
    }

    // if not, update sigma using the Newton-Raphson method
    sigma = sigma - (optionPriceCalculated - optionPrice) / vega;
  }

  // if the loop doesn't converge within the maximum number of iterations, return NaN
  return NaN;
}

function normCDF(x: number): number {
  // calculate the cumulative distribution function of a standard normal distribution using the Abramowitz and Stegun approximation
  const t = 1 / (1 + 0.2316419 * Math.abs(x));
  const d = 0.3989423 * Math.exp(-x * x / 2);
  const p = d * t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274))));
  return x >= 0 ? 1 - p : p;
}

function normPDF(x: number): number {
  // calculate the probability density function of a standard normal distribution
  return Math.exp(-x * x / 2) / Math.sqrt(2 * Math.PI);
}
```
